const base=path.resolve(import.meta.dirname,'../static/pet-acorn-mailbox-proof-20261027'),near=(a,b,e=1e-6)=>assert.ok(Math.abs(a-b)<e,a+' != '+b),box=m=>new T.Box3().setFromObject(m,true),sha=b=>crypto.createHash('sha256').update(b).digest('hex');
function topology(g){const p=g.attributes.position,n=g.attributes.normal,ix=g.index,edges=new Map(),v=i=>new T.Vector3().fromBufferAttribute(p,i),key=i=>v(i).toArray().map(x=>Math.round(x*1e7)).join(':');let volume=0,degenerate=0,negative=0;for(let i=0;i<(ix?ix.count:p.count);i+=3){const ids=[0,1,2].map(k=>ix?ix.getX(i+k):i+k),[a,b,c]=ids.map(v),cross=b.clone().sub(a).cross(c.clone().sub(a));if(cross.lengthSq()<1e-20){degenerate++;continue;}volume+=a.dot(b.clone().cross(c))/6;const normal=ids.map(k=>new T.Vector3().fromBufferAttribute(n,k)).reduce((a,b)=>a.add(b),new T.Vector3()).normalize();if(cross.clone().normalize().dot(normal)<=0)negative++;const ks=ids.map(key);for(let j=0;j<3;j++){const a=ks[j],b=ks[(j+1)%3],k=[a,b].sort().join('|'),r=edges.get(k)||{count:0,direction:0};r.count++;r.direction+=a<b?1:-1;edges.set(k,r);}}return{volume,degenerate,negative,badEdges:[...edges.values()].filter(x=>x.count!==2||x.direction!==0).length};}
function solidInside(mesh,point){const positions=mesh.geometry.attributes.position,index=mesh.geometry.index;let sum=0;for(let i=0;i<(index?index.count:positions.count);i+=3){const [a,b,c]=[0,1,2].map(k=>new T.Vector3().fromBufferAttribute(positions,index?index.getX(i+k):i+k).applyMatrix4(mesh.matrixWorld).sub(point)),la=a.length(),lb=b.length(),lc=c.length();sum+=2*Math.atan2(a.dot(b.clone().cross(c)),la*lb*lc+a.dot(b)*lc+b.dot(c)*la+c.dot(a)*lb);}return Math.abs(sum)>3.5*Math.PI;}
const fixture=season=>{const world=Town.createWorld(),model=Scene.buildWorld(T,world,{},null,null,season),item=build(T);return{world,model,item,dispose(){item.dispose();model.dispose();}};};
test('every actual wall, roof, shingle, hinge and foot part has closed oriented positive volume with finite normals',()=>{const a=build(T);assert.equal(a.parts.length,57);for(const p of a.parts){const r=topology(p.mesh.geometry);assert.equal(r.badEdges,0,p.id);assert.equal(r.degenerate,0,p.id);assert.equal(r.negative,0,p.id);assert.ok(r.volume>0,p.id);}near(a.bounds.min[1],0);assert.equal(a.inspect().invalidNormals,0);assert.equal(a.inspect().invalidPositions,0);assert.ok(a.tiles.length===14&&a.budget.triangles<8000);a.dispose();});
test('front hatch and letter slot are actual holes and the cavity is empty in nine sampled front rays',()=>{const a=build(T),ray=new T.Raycaster();a.front.material.side=T.DoubleSide;for(const y of[1.08,1.18,1.30])for(const x of[-.20,0,.20]){ray.set(new T.Vector3(x,y,0),new T.Vector3(0,0,1));assert.equal(ray.intersectObject(a.front,false).length,0);}ray.set(new T.Vector3(0,1.565,0),new T.Vector3(0,0,1));assert.equal(ray.intersectObject(a.front,false).length,0);ray.set(new T.Vector3(.45,1.29,1),new T.Vector3(0,0,-1));assert.ok(ray.intersectObject(a.front,false).length>0);ray.set(new T.Vector3(0,1.20,0),new T.Vector3(-1,0,0));a.shell.material.side=T.DoubleSide;const hits=ray.intersectObject(a.shell,false).map(h=>h.distance).sort((a,b)=>a-b);assert.ok(hits.length>=2);near(hits.at(-1)-hits[0],.08,1e-5);a.setAngle(95);for(const y of[1.08,1.18,1.30])for(const x of[-.20,0,.20]){ray.set(new T.Vector3(x,y,0),new T.Vector3(0,0,1));assert.equal(ray.intersectObject(a.door,false).length,0);}a.dispose();});
test('stone feet, base, post, neck and acorn roof have actual supported overlaps; hatch trim and knob contact their panel',()=>{const a=build(T);for(const foot of a.feet){near(box(foot).min.y,0);assert.ok(box(foot).max.y>box(a.base).min.y);}assert.ok(box(a.base).max.y>box(a.post).min.y);assert.ok(box(a.post).max.y>box(a.neck).min.y);assert.ok(box(a.neck).max.y>box(a.shell).min.y);assert.ok(box(a.shell).max.y>box(a.roof).min.y);const slotContact=new T.Vector3(0,1.6125,.34975);assert.ok(solidInside(a.front,slotContact)&&solidInside(a.slotRim,slotContact),'slot rim must intersect actual front solid');for(const part of a.parts.filter(p=>p.role==='fixed-shaft-collar')){const contact=new T.Vector3(part.mesh.position.x,spec.hingeAxis[1]+.011,spec.hingeAxis[2]);assert.ok(solidInside(a.pin,contact)&&solidInside(part.mesh,contact),part.id+' actual shaft contact');assert.ok(box(a.pin).min.x<box(part.mesh).min.x&&box(a.pin).max.x>box(part.mesh).max.x,'shaft extends through collar');}for(const id of['envelope-fold-left','envelope-fold-right']){const mesh=a.parts.find(p=>p.id===id).mesh,contact=mesh.position.clone();contact.z-=.004;contact.applyMatrix4(a.moving.matrixWorld);assert.ok(solidInside(mesh,contact)&&solidInside(a.door,contact),id+' must enter actual hatch panel');}const doorBox=box(a.door);for(const id of ['hatch-panel-gold-inlay','letter-envelope-badge-outline','hatch-round-knob'])assert.ok(doorBox.intersectsBox(box(a.parts.find(p=>p.id===id).mesh)),id);for(const mount of a.mounts){const moving=mount.parent===a.moving;assert.ok((moving?box(a.door):box(a.front)).intersectsBox(box(mount)),mount.name);}a.dispose();});
test('five real hinge bores share one through-pin axis with radial air clearance and external webs leave the bore unobstructed',()=>{const a=build(T),ray=new T.Raycaster(),axis=spec.hingeAxis;a.pin.material.side=T.DoubleSide;for(const k of a.knuckles){k.material.side=T.DoubleSide;const p=k.getWorldPosition(new T.Vector3());ray.set(p,new T.Vector3(0,0,1));const ds=[...new Set(ray.intersectObject(k,false).map(h=>Math.round(h.distance*1e7)/1e7))].sort((a,b)=>a-b);assert.equal(ds.length,2,k.name);near(ds[0],spec.hingeInnerRadius);near(ds[1],spec.hingeOuterRadius);assert.ok(ds[0]>spec.pinRadius);}ray.set(new T.Vector3(-1,axis[1],axis[2]),new T.Vector3(1,0,0));assert.equal(ray.intersectObjects(a.knuckles,false).length,0);assert.equal(ray.intersectObjects(a.mounts,false).length,0);assert.ok(ray.intersectObject(a.pin,false).length>0);a.dispose();});
test('twenty finite real hatch poses stay ahead of the shell and below the roof while the hinge axis and fixed geometry stay fixed',()=>{const a=build(T),fixed=a.parts.filter(p=>p.mesh.parent===a.group),matrices=fixed.map(p=>p.mesh.matrixWorld.toArray()),bounds=a.bounds;assert.equal(a.poseWitnesses.length,20);for(let angle=0;angle<=95;angle+=5){a.setAngle(angle);assert.equal(a.angle,angle);const b=box(a.door);assert.ok(b.min.z>box(a.front).max.z+.005);assert.ok(b.max.y<box(a.roof).min.y-.05);assert.deepEqual(a.moving.position.toArray(),[...spec.hingeAxis]);assert.deepEqual(fixed.map(p=>p.mesh.matrixWorld.toArray()),matrices);const envelope=new T.Box3(new T.Vector3(...bounds.min),new T.Vector3(...bounds.max));assert.ok(envelope.containsBox(box(a.group)));}a.dispose();});
test('manual fractional angle is accepted; invalid inputs and disposed controls cannot mutate or allocate geometry',()=>{const a=build(T),other=build(T),geometries=[...a.resources.geometries],materials=[...a.resources.materials];a.setAngle(37.625);near(a.angle,37.625);for(const invalid of[-.01,95.01,NaN,Infinity,'12',null])assert.throws(()=>a.setAngle(invalid),/angle_invalid/);near(a.angle,37.625);assert.deepEqual([...a.resources.geometries],geometries);assert.deepEqual([...a.resources.materials],materials);let count=0;const resources=Object.values(a.resources).flatMap(s=>[...s]);for(const r of resources)r.addEventListener('dispose',()=>count++);a.dispose();a.dispose();assert.equal(count,resources.length);assert.equal(a.group.children.length,0);assert.throws(()=>a.setAngle(0),/disposed/);assert.equal(other.disposed,false);other.dispose();});
test('one real village point has twenty sole/floor supports and finite walkability with unchanged world, manual character scale and scene registries',()=>{const f=fixture('autumn'),before=JSON.stringify(f.world),surfaces=f.model.surfaces.slice(),occluders=f.model.occluders.slice(),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.equal(p.supports.length,20);for(const row of p.supports)near(row.soleMinusFloor,0);assert.ok(p.finiteWalkability.samples>150);assert.equal(p.finiteWalkability.blocked,0);assert.equal(JSON.stringify(f.world),before);assert.deepEqual(f.model.surfaces,surfaces);assert.deepEqual(f.model.occluders,occluders);assert.equal(p.notRegisteredAsTownSurface,true);assert.equal(p.normalPlacement,false);assert.equal(p.bodyBinding,null);near(p.characterScaleReference.frameWorldHeight,1.65);assert.deepEqual(f.item.group.scale.toArray(),[1,1,1]);f.dispose();});
test('all actual road triangles and141 original card envelopes clear the full hatch envelope, while invalid/overlapping anchors are rejected',()=>{const f=fixture('winter'),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.equal(p.roads.reduce((n,r)=>n+r.triangles,0),2022);assert.ok(p.minimumRoadGap>.33);assert.equal(p.originalSpriteEnvelopeClearance.checkedCards,141);assert.ok(p.originalSpriteEnvelopeClearance.minimumGap>.63);assert.equal(p.originalSpriteEnvelopeClearance.physicalFixtureVolumes,false);assert.equal(p.originalSpriteEnvelopeClearance.allCameraProjectionOcclusionGuaranteed,false);assert.ok(p.buildingProxyClearance.every(x=>!x.intersects));assert.equal(f.model.scene.userData.originalArtRevision,'placement-originals1');const rect={minX:0,maxX:1,minZ:0,maxZ:1};near(triangleRectangleDistance([[2,0],[3,0],[2,1]],rect),1);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:NaN,y:0}),/anchor_invalid/);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:f.world.width*.48,y:f.world.height*.52}),/road_clearance|footprint_blocked/);f.dispose();});
test('actual complete-pose bounds fit finite320/390 continuous yaw/pitch/roll views without model rescaling',()=>{const a=build(T);for(const width of[300,370])for(let yaw=-180;yaw<=180;yaw+=15)for(const pitch of[-80,12,88]){const f=fitView(T,a.bounds,{yaw,pitch,roll:yaw/3,distance:1},width/350);for(const n of Object.values(f.ndcBounds))assert.ok(Number.isFinite(n)&&Math.abs(n)<.87);}assert.deepEqual(a.group.scale.toArray(),[1,1,1]);assert.ok(a.budget.meshes<=60&&a.budget.materials<=6&&a.budget.triangles<8000);assert.equal(a.budget.textures,0);assert.equal(a.budget.lights,0);a.dispose();});
test('manifest pins the existing unmodified raw and actual dependencies; export is raw renderer output and all delivery/economy/save/new-art gates stay false',async()=>{const m=JSON.parse(fs.readFileSync(path.join(base,'input-manifest.json')));assert.equal(m.model_id,spec.id);assert.equal(m.unit_id,spec.unit);assert.equal(m.source_original.sha256,spec.sourceSHA);assert.equal(sha(fs.readFileSync(path.join(base,'reference.png'))),spec.sourceSHA);assert.equal(m.base_main_sha,'3d6a7ef72908362c9e1e664ac61794d388f90b78');for(const key of['normal_game_changes','new_raw_PNGs','new_original_PNG_designs','imagegen_calls','new_mesh_library_candidates'])assert.equal(m[key],0);for(const r of m.inputs){const bytes=fs.readFileSync(path.resolve(import.meta.dirname,'..',r.path));assert.equal(bytes.length,r.bytes);assert.equal(sha(bytes),r.sha256);}for(const r of m.files){const bytes=fs.readFileSync(path.join(base,r.path));assert.equal(sha(bytes),r.sha256);}const v=fs.readFileSync(path.join(base,'viewer.mjs'),'utf8');assert.match(v,/toDataURL\('image\/png'\)/);assert.match(v,/fetch\('\/__capture\/mailbox'/);assert.match(v,/visibilitychange/);assert.match(v,/pagehide/);assert.doesNotMatch(v,/localStorage|sessionStorage|saveGame|registerAsset/);assert.match(fs.readFileSync(path.join(base,'SPEC.json'),'utf8'),/"delivery_rewards": false/);const mock=()=>{const nodes={stage:{dataset:{}},status:{textContent:''},report:{textContent:''}};return{nodes,doc:{getElementById:id=>nodes[id]}};};const link=mock();assert.equal(await startPreview({doc:link.doc,load:async()=>{throw new SyntaxError("The requested module '/example.mjs' does not provide an export named 'expectedPart'");}}),false);let failure=JSON.parse(link.nodes.report.textContent).startup;assert.equal(failure.failure.category,'module_missing_export');assert.equal(failure.failure.detail,'expectedPart');assert.equal(link.nodes.stage.dataset.failed,'true');assert.doesNotMatch(link.nodes.report.textContent,/example\.mjs/);const init=mock();assert.equal(await startPreview({doc:init.doc,load:async()=>({start:async()=>{throw new ReferenceError('PetTownScene is not defined');},cleanup:()=>{throw Error('cleanup_failed');}})}),false);failure=JSON.parse(init.nodes.report.textContent).startup;assert.equal(failure.failure.category,'missing_runtime_binding');assert.equal(failure.cleanupFailed,true);assert.match(init.nodes.status.textContent,/読み込めません/);const ready=mock();assert.equal(await startPreview({doc:ready.doc,load:async()=>({start:async phase=>{phase('main_started');ready.nodes.stage.dataset.ready='true';phase('ready');ready.nodes.report.textContent='real-frame-proof';}})}),true);assert.equal(ready.nodes.report.textContent,'real-frame-proof');assert.equal(failureDetails(Error('https://example.invalid/private?token=x')).detail,null);assert.match(v,/export function cleanup/);assert.match(v,/try\{task\(\);\}catch/);assert.match(fs.readFileSync(path.join(base,'entry.mjs'),'utf8'),/finally\{complete=true/);});
